// real, src/events.ts
emit(event: E): void {
  this.queue.push(event);
  if (this.delivering) return; // the outer emit() drains the queue
  this.delivering = true;
  try {
    for (let next = this.queue.shift(); next !== undefined; next = this.queue.shift()) {
      for (const listener of [...this.listeners]) {
        if (!this.listeners.has(listener)) continue;
        try {
          listener(next);
        } catch (error) {
          try {
            this.onListenerError(error, next);
          } catch {
            // An error handler that throws must not break the lot either.
          }
        }
      }
    }
  } finally {
    this.delivering = false;
  }
}

// real, src/free-index.ts (constructor and push)
constructor(private readonly spots: readonly ParkingSpot[]) {
  this.inHeap = spots.map(() => false);
  spots.forEach((spot, i) => {
    this.numberOf.set(spot, i);
    if (spot.isFree) this.push(spot.size, i);
  });
}

private push(size: SpotSize, i: number): void {
  let heap = this.heaps.get(size);
  if (heap === undefined) {
    heap = new MinHeap();
    this.heaps.set(size, heap);
  }
  heap.push(i);
  this.inHeap[i] = true;
}

// real, src/free-index.ts MinHeap.pop() sift-down
let i = 0;
for (;;) {
  const l = 2 * i + 1;
  const r = l + 1;
  let m = i;
  if (l < a.length && a[l]! < a[m]!) m = l;
  if (r < a.length && a[r]! < a[m]!) m = r;   // S11 removed this line
  if (m === i) break;
  [a[m], a[i]] = [a[i]!, a[m]!];
  i = m;
}

