import type { Availability, ParkingLot } from "./parking-lot.js";

export interface LevelRow { level: number; free: number; total: number }

export class LevelBoard {
  private readonly rows = new Map<string, Availability>();
  private readonly unsubscribe: () => void;

  constructor(lot: ParkingLot) {
    for (const r of lot.availability()) this.rows.set(`${r.level}:${r.size}`, r);
    this.unsubscribe = lot.subscribe((r) => {
      this.rows.set(`${r.level}:${r.size}`, r); // absolute count: just replace
    });
  }

  levels(): LevelRow[] {
    const byLevel = new Map<number, LevelRow>();
    for (const r of this.rows.values()) {
      const l = byLevel.get(r.level) ?? { level: r.level, free: 0, total: 0 };
      l.free += r.free;
      l.total += r.total;
      byLevel.set(r.level, l);
    }
    return [...byLevel.values()];
  }

  close(): void {
    this.unsubscribe();
  }
}

// test (vitest)
it("per-level totals follow park and exit; close() stops updates", () => {
  const lot = new ParkingLot({
    layout: [["small", "compact"], ["large", "compact"]],
    pricing: new HourlyPricing({ motorcycle: 1, car: 1, truck: 1 }),
    clock: new ManualClock(0),
  });
  const board = new LevelBoard(lot);
  const t = lot.park("T1", "truck"); // only L1 large fits
  expect(board.levels()).toEqual([
    { level: 0, free: 2, total: 2 },
    { level: 1, free: 1, total: 2 },
  ]);
  lot.exit(t.id);
  expect(board.levels()[1]!.free).toBe(2);
  board.close();
  lot.park("T2", "truck");
  expect(board.levels()[1]!.free).toBe(2); // no longer updated
});

