import { FreeSpotIndex } from "./free-index.js";
import { ParkingSpot } from "./spot.js";
import { SPOT_SIZES, type SpotSize } from "./types.js";

function rng(seed: number) { // mulberry32, same as test/invariants.test.ts
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function run(n: number, steps: number, mode: "scan" | "index", seed: number) {
  const spots = Array.from({ length: n }, (_, i) =>
    new ParkingSpot(`S${i}`, Math.floor(i / 100), i % 100, SPOT_SIZES[i % 3]!));
  const index = new FreeSpotIndex(spots);
  const find = mode === "index"
    ? (s: SpotSize) => index.nearest(s)
    : (s: SpotSize) => spots.find((x) => x.isFree && x.size === s);
  const rand = rng(seed);
  const taken: ParkingSpot[] = [];
  let id = 0;
  const take = (size: SpotSize) => {
    const s = find(size);
    if (s !== undefined) { s.reserve(`t${id++}`); taken.push(s); }
    return s;
  };
  const release = () => {
    const k = Math.floor(rand() * taken.length);
    const s = taken[k]!;
    taken[k] = taken[taken.length - 1]!;
    taken.pop();
    s.release(s.heldBy!);
    if (mode === "index") index.released(s);
  };
  // Fill to ~80% through the allocation itself (front-loaded, like a real lot). Not timed.
  while (taken.length < n * 0.8) take(SPOT_SIZES[Math.floor(rand() * 3)]!);
  let checksum = 0;
  const t0 = process.hrtime.bigint();
  for (let i = 0; i < steps; i++) {
    if (taken.length > 0 && rand() < 0.5) release();
    else checksum += take(SPOT_SIZES[Math.floor(rand() * 3)]!)?.position ?? -1;
  }
  const ns = Number(process.hrtime.bigint() - t0);
  return { nsPerOp: ns / steps, checksum };
}

const median = (xs: number[]) => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)]!;
for (const n of [100, 1_000, 10_000, 100_000]) {
  const steps = 20_000;
  const result: Record<string, number> = {};
  for (const mode of ["scan", "index"] as const) {
    run(n, steps, mode, 99); // warm-up (JIT)
    const runs = [1, 2, 3, 4, 5].map((seed) => run(n, steps, mode, seed));
    result[mode] = median(runs.map((r) => r.nsPerOp));
    result[`${mode}Sum`] = runs.reduce((s, r) => s + r.checksum, 0);
  }
  if (result.scanSum !== result.indexSum) throw new Error(`n=${n}: scan and index chose different spots`);
  console.log(`n=${n}  scan ${result.scan!.toFixed(0)} ns/op  index ${result.index!.toFixed(0)} ns/op`);
}

