// real, src/allocation.ts
export interface AllocationStrategy {
  readonly name: string;
  choose(vehicle: VehicleType, free: FreeSpots): ParkingSpot | undefined;
}

export const smallestFitFirst: AllocationStrategy = {
  name: "smallest-fit-first",
  choose: (vehicle, free) => {
    for (const size of fittingSizes(vehicle)) {
      const spot = free.nearest(size);
      if (spot !== undefined) return spot;
    }
    return undefined;
  },
};

// illustrative (NOT in the repo): board side of a sequenced stream
interface SeqEvent { seq: number; row: Availability }
let lastSeq = -1;
function onEvent(e: SeqEvent) {
  if (e.seq <= lastSeq) return;                 // duplicate or old: absolute rows make this safe
  if (e.seq !== lastSeq + 1) return resync();    // gap: fetch a fresh snapshot
  rows.set(`${e.row.level}:${e.row.size}`, e.row);
  lastSeq = e.seq;
}

